window.VO = [{"id":"n01","text":"You're the only witness to this crash.","at":0.24,"t0":0.12,"t1":1.865},{"id":"n02","text":"Watch closely.","at":4.17,"t0":2.085,"t1":3.04},{"id":"n03","text":"The driver doesn't stop.","at":11.28,"t0":5.64,"t1":7.085},{"id":"n04","text":"So you're all this man has.","at":14.77,"t0":7.385,"t1":8.77},{"id":"n05","text":"How fast was the rickshaw going when it smashed into the cart?","at":20.74,"t0":10.37,"t1":13.46},{"id":"n06","text":"And the broken glass: left of the cart, or right?","at":30.02,"t0":15.01,"t1":17.84},{"id":"n07","text":"There was no broken glass.","at":41.68,"t0":20.84,"t1":22.31},{"id":"n08","text":"Go back and look.","at":45.52,"t0":22.76,"t1":23.78},{"id":"n09","text":"He never asked if there was any.","at":49.76,"t0":24.88,"t1":26.64},{"id":"n10","text":"He asked where it was.","at":53.88,"t0":26.94,"t1":28.215},{"id":"n11","text":"And some of you could almost see it.","at":57.43,"t0":28.715,"t1":30.28},{"id":"n12","text":"Because your brain doesn't replay a memory.","at":61.16,"t0":30.58,"t1":32.71},{"id":"n13","text":"It rebuilds it, every time, with whatever it's just heard.","at":65.92,"t0":32.96,"t1":36.19},{"id":"n14","text":"Even one word can do it.","at":73.48,"t0":36.74,"t1":38.335},{"id":"n15","text":"In nineteen seventy-four, students whose question said smashed, not hit, were twice as likely, a week later, to remember broken glass.","at":77.27,"t0":38.635,"t1":46.59},{"id":"n16","text":"There wasn't any.","at":93.88,"t0":46.94,"t1":48.01},{"id":"n17","text":"That's why judges usually stop questions like his.","at":97.12,"t0":48.56,"t1":51.45},{"id":"n18","text":"Out here, nobody did.","at":103.5,"t0":51.75,"t1":53.1},{"id":"n19","text":"So if you picked a side, the police are now looking for broken glass.","at":107,"t0":53.5,"t1":57.31},{"id":"n20","text":"His glass is fine.","at":115.32,"t0":57.66,"t1":58.85},{"id":"n21","text":"Said there wasn't any? Good.","at":121.2,"t0":60.6,"t1":62.19},{"id":"n22","text":"What hit his windscreen?","at":125.18,"t0":62.59,"t1":63.92}];
